; TI-BASIC Program - Generated by tibasic_compiler.py
; Nova-16 Assembly Language

ORG 0x1000

; Initialize TI-BASIC system
MOV P8,0xF000    ; Parameter stack pointer
MOV VX,0         ; Text cursor X
MOV VY,0         ; Text cursor Y

; Main program entry point
main:
    CALL tibasic_main
    HLT

; TI-BASIC main routine
tibasic_main:
    ; Main program code will be inserted here
    ; ClrHome - clear screen
    MOV P0,0
    SFILL P0
    ; Load literal 1
    MOV P0,1
    SUB P8,2
    MOV [P8],P0
    ; FOR I = start To end
    ; Store end value
    ; Load literal 100
    MOV P0,100
    SUB P8,2
    MOV [P8],P0
    MOV P0,[P8]
    ADD P8,2
    MOV R0,0x2012
    MOV [R0+0],P0
    ; Initialize I
    MOV P0,[P8]
    ADD P8,2
    MOV R0,0x2010
    MOV [R0+0],P0
for_0:
    ; A = expression
    ; Load I
    MOV R0,0x2010
    MOV P0,[R0+0]
    SUB P8,2
    MOV [P8],P0
    ; Store result to A
    MOV P0,[P8]
    ADD P8,2
    MOV R0,0x2000
    MOV [R0+0],P0
    ; END FOR I
    ; Increment I
    MOV R0,0x2010
    MOV P0,[R0+0]
    INC P0
    MOV [R0+0],P0
    ; Check if I <= end
    MOV R0,0x2012
    MOV P2,[R0+0]
    CMP P0,P2
    JLE for_0
for_0_end:
    RET

; Print string routine
print_string:
    ; Print null-terminated string at address in P0
    MOV R0,P0
print_loop:
    MOV R1,[R0+0]
    CMP R1,0
    JZ print_done
    ; TODO: Implement character output
    ADD R0,1
    JMP print_loop
print_done:
    RET

; Print number routine (decimal output)
print_number:
    ; Convert 16-bit number in P0 to decimal and print
    MOV P1,P0
    MOV R2,0
    MOV R4,0
    CMP P1,0
    JGE positive
    MOV R2,1
    NEG P1
positive:
    ; Print thousands digit
    MOV P3,1000
    CALL print_digit
    ; Print hundreds digit
    MOV P3,100
    CALL print_digit
    ; Print tens digit
    MOV P3,10
    CALL print_digit
    ; Print ones digit
    MOV P0,P1
    ADD P0,48
    MOV P1,0x0F
    CHAR P0,P1
    CMP R4,0
    JNZ done_print
    ; Print '0' if no digits printed yet
    MOV P0,48
    MOV P1,0x0F
    CHAR P0,P1
done_print:
    CMP R2,0
    JZ no_sign
    ; Print '-'
    MOV P0,45
    MOV P1,0x0F
    CHAR P0,P1
no_sign:
    RET

; Advance cursor by P0 pixels, with line wrapping
advance_cursor:
    ; Check if adding P0 would exceed screen width
    MOV P2,VX
    ADD P2,P0
    CMP P2,256
    JC no_wrap
    ; Wrap to next line
    MOV VX,0
    ADD VY,8
    JMP advance_done
no_wrap:
    ADD VX,P0
advance_done:
    RET

; Print digit subroutine (modifies P1, P3)
print_digit:
    MOV R5,0
digit_loop:
    CMP P1,P3
    JC digit_done
    SUB P1,P3
    INC R5
    JMP digit_loop
digit_done:
    CMP R4,0
    JNZ print_this_digit
    CMP R5,0
    JZ skip_this_digit
print_this_digit:
    MOV R4,1
    ADD R5,48
    MOV P0,R5
    MOV P1,0x0F
    CHAR P0,P1
skip_this_digit:
    RET
